-- Mensaje 138 (6-nov-2026) · La bala del re-impulso: el contenido.
-- Cerebro v20 → v21 (la bala la escoges tú, y una ya dicha también re-impulsa; «lo que encontramos» no es la bala),
-- 5 reglas, 6 tarjetas y 2 preguntas de quiz.
-- Todo protegido: cada cambio se hace solo si lo de hoy es exactamente lo esperado. El chequeo del final aborta si algo no quedó.
-- Correrlo dos veces no cambia nada.

DO $c$ DECLARE v int; BEGIN
  IF EXISTS (SELECT 1 FROM public.doctrina WHERE is_active AND strpos(body, $v$Responderle bien solo **detiene la caída** — lo que vuelve a subirlo es **una bala**. Si las gastaste todas presumiendo al principio, llegas a ese momento con menos de dónde escoger.$v$) > 0) THEN RAISE NOTICE 'El Cerebro ya tiene el cambio del 138.'; RETURN; END IF;
  SELECT max(version) INTO v FROM public.doctrina WHERE is_active;
  IF v <> 20 THEN RAISE EXCEPTION 'se esperaba el Cerebro v20 y está el v%', v; END IF;
  IF (SELECT count(*) FROM public.doctrina WHERE version = v AND is_active AND strpos(body, $v$Responderle bien solo **detiene la caída** — lo que vuelve a subirlo es **una bala nueva**. Si las gastaste presumiendo al principio, llegas a ese momento con la mano vacía.$v$) > 0) <> 1 THEN RAISE EXCEPTION 'el Cerebro vigente no tiene el texto esperado (cambio 1)'; END IF;
  IF (SELECT count(*) FROM public.doctrina WHERE version = v AND is_active AND strpos(body, $v$ante una objeción se reimpulsa con una bala nueva.$v$) > 0) <> 1 THEN RAISE EXCEPTION 'el Cerebro vigente no tiene el texto esperado (cambio 2)'; END IF;
  IF (SELECT count(*) FROM public.doctrina WHERE version = v AND is_active AND strpos(body, $v$4. **Re-impulsa con una bala** `CAMPO`: una sola, y cierras. Tres de golpe sería vaciar el cargador.$v$) > 0) <> 1 THEN RAISE EXCEPTION 'el Cerebro vigente no tiene el texto esperado (cambio 3)'; END IF;
  IF (SELECT count(*) FROM public.doctrina WHERE version = v AND is_active AND strpos(body, $v$   RE-IMPULSAS con una bala NUEVA ───┘$v$) > 0) <> 1 THEN RAISE EXCEPTION 'el Cerebro vigente no tiene el texto esperado (cambio 4)'; END IF;
  IF (SELECT count(*) FROM public.doctrina WHERE version = v AND is_active AND strpos(body, $v$**Y la bala tiene que subir el impulso** `CAMPO`. Una bala nueva es un beneficio o un dato que todavía no habías dicho; decir lo mismo con otras palabras es repetirla. Una que ya usaste también se vale si ahora la conectas con la objeción: ante *"está caro"*, *"por eso le sale más barato: ya no pierde cambios por quedarse sin aceite"*. Lo que no sirve es repetirla tal cual, sin conectarla con nada: repetir un argumento ya usado no sube nada, comunica que ya no tienes más, y eso baja el impulso en lugar de subirlo.$v$) > 0) <> 1 THEN RAISE EXCEPTION 'el Cerebro vigente no tiene el texto esperado (cambio 5)'; END IF;
  INSERT INTO public.doctrina (version, section_key, order_index, title, body, is_active, created_by)
  SELECT v + 1, section_key, order_index, title, replace(replace(replace(replace(replace(body, $v$Responderle bien solo **detiene la caída** — lo que vuelve a subirlo es **una bala nueva**. Si las gastaste presumiendo al principio, llegas a ese momento con la mano vacía.$v$, $v$Responderle bien solo **detiene la caída** — lo que vuelve a subirlo es **una bala**. Si las gastaste todas presumiendo al principio, llegas a ese momento con menos de dónde escoger.$v$), $v$ante una objeción se reimpulsa con una bala nueva.$v$, $v$ante una objeción se reimpulsa con la bala que escojas para ese momento.$v$), $v$4. **Re-impulsa con una bala** `CAMPO`: una sola, y cierras. Tres de golpe sería vaciar el cargador.$v$, $v$4. **Re-impulsa con una bala** `CAMPO`: una sola, y cierras. Tres de golpe sería vaciar el cargador. «Lo que encontramos» no es la bala: es el paso 3. La bala va aparte, después.$v$), $v$   RE-IMPULSAS con una bala NUEVA ───┘$v$, $v$   RE-IMPULSAS con una bala ─────────┘$v$), $v$**Y la bala tiene que subir el impulso** `CAMPO`. Una bala nueva es un beneficio o un dato que todavía no habías dicho; decir lo mismo con otras palabras es repetirla. Una que ya usaste también se vale si ahora la conectas con la objeción: ante *"está caro"*, *"por eso le sale más barato: ya no pierde cambios por quedarse sin aceite"*. Lo que no sirve es repetirla tal cual, sin conectarla con nada: repetir un argumento ya usado no sube nada, comunica que ya no tienes más, y eso baja el impulso en lugar de subirlo.$v$, $v$**La bala la escoges tú** `CAMPO`: la que te convenga para volver a subir el impulso de ese cliente en ese momento. Puede ser una que todavía no habías dicho, o una que ya dijiste. Volver a decir una ya dicha, aunque sea tal cual, también se vale: no es igual de efectivo, pero muchas veces ayuda, porque le ratifica que lo que dijiste es verdad y le da seguridad. Y una ya dicha pega más si la conectas con la objeción: ante *"está caro"*, *"por eso le sale más barato: ya no pierde cambios por quedarse sin aceite"*. Unas balas van a ser más efectivas que otras con distintos clientes: leer cuál te conviene usar en ese momento es trabajo del vendedor. Lo que no es bala es algo vago que cualquiera diría.$v$), true, created_by
  FROM public.doctrina WHERE version = v AND is_active;
  UPDATE public.doctrina SET is_active = false WHERE is_active AND version = v;
END $c$;

UPDATE public.reglas SET resumen = $v$Balas: hechos positivos y concretos sobre el producto, el servicio (tú, tu empresa y cómo se lo haces llegar) o el precio. Con cada una subes el valor o bajas el costo. Se sueltan poco a poco, conforme hace falta subir el impulso: en la presentación unas tres cosas positivas antes del precio, y ante una objeción la bala que el vendedor escoja para ese momento. LA PRUEBA DE UNA BALA: ¿la competencia podría decir exactamente lo mismo? Si sí, no era bala. En la práctica todo es imaginario: no se califica si es real, sino si es concreto.$v$, updated_at = now()
WHERE id = 'present.balas' AND resumen = $v$Balas: hechos positivos y concretos sobre el producto, el servicio (tú, tu empresa y cómo se lo haces llegar) o el precio. Con cada una subes el valor o bajas el costo. Se sueltan poco a poco, conforme hace falta subir el impulso: en la presentación unas tres cosas positivas antes del precio, y ante una objeción una bala nueva. LA PRUEBA DE UNA BALA: ¿la competencia podría decir exactamente lo mismo? Si sí, no era bala. En la práctica todo es imaginario: no se califica si es real, sino si es concreto.$v$;

UPDATE public.reglas SET resumen = $v$Feel, Felt, Found para la preocupación seria o personal: «entiendo cómo se siente», «otros sintieron lo mismo», «lo que encontraron fue…». No termina en la tercera F: sigue una bala y el cierre con acción. «Lo que encontraron» no es la bala: es la tercera F. LA PRUEBA: ante una objeción seria, ¿el vendedor la valida sin discutir, dice que otros sintieron lo mismo y lo que encontraron, y avanza? En la práctica los otros clientes se imaginan. Si falta una de las tres F, está a medias.$v$, updated_at = now()
WHERE id = 'objection.fff' AND resumen = $v$Feel, Felt, Found para la preocupación seria o personal: «entiendo cómo se siente», «otros sintieron lo mismo», «lo que encontraron fue…». No termina en la tercera F: sigue una bala y el cierre con acción. LA PRUEBA: ante una objeción seria, ¿el vendedor la valida sin discutir, dice que otros sintieron lo mismo y lo que encontraron, y avanza? En la práctica los otros clientes se imaginan. Si falta una de las tres F, está a medias.$v$;

UPDATE public.reglas SET resumen = $v$El Círculo de Cierre: atravesar la objeción, re-impulsar con una bala y volver a cerrar con acción. Atravesar solo detiene la caída del impulso: no lo sube. LA PRUEBA: después de atravesar la objeción, ¿el vendedor sube el impulso con una bala —la que escoja: una que no había dicho, o una ya dicha, aunque la repita tal cual— y vuelve a pedir la decisión con una pregunta de acción? «Lo que encontraron» de FFF no es la bala: es el paso anterior.$v$, updated_at = now()
WHERE id = 'objection.circulo_de_cierre' AND resumen = $v$El Círculo de Cierre: atravesar la objeción, re-impulsar con una bala y volver a cerrar con acción. Atravesar solo detiene la caída del impulso: no lo sube. LA PRUEBA: después de atravesar la objeción, ¿el vendedor sube el impulso con una bala —nueva, o una ya dicha si ahora la conecta con la objeción— y vuelve a pedir la decisión con una pregunta de acción?$v$;

UPDATE public.reglas SET resumen = $v$Atravesar la objeción y cerrar de inmediato, saltándose la bala: pides una decisión en el punto más bajo de la conversación. LA PRUEBA: después de atender la objeción, ¿el vendedor pide la decisión sin dar antes ninguna bala que suba el impulso? «Lo que encontraron» de FFF no cuenta como bala, aunque sea concreto: es la tercera F, y la bala va aparte. Una bala ya dicha, aunque la repita tal cual, sí cuenta.$v$, updated_at = now()
WHERE id = 'objection.cierra_sin_bala' AND resumen = $v$Atravesar la objeción y cerrar de inmediato, saltándose la bala: pides una decisión en el punto más bajo de la conversación. LA PRUEBA: después de atender la objeción, ¿el vendedor pide la decisión sin dar antes ninguna bala que suba el impulso?$v$;

UPDATE public.reglas SET resumen = $v$Volver a decir una bala que ya dijiste también re-impulsa: le ratifica al cliente que lo que dijiste es verdad y le da seguridad. No es igual de efectivo que la bala que mejor le pega a ese cliente en ese momento, pero no es falla: escoger cuál usar es trabajo del vendedor. LA PRUEBA: como re-impulso, ¿el vendedor vuelve a decir algo concreto que ya había dicho, igual o conectado con la objeción? Entonces sí dio una bala: no se saltó la bala, sin importar cuántas veces lo haya dicho antes. Si es vago, no es bala.$v$, tipo = $v$principio$v$, severidad_default = NULL, cita_cerebro = $v$le ratifica que lo que dijiste es verdad y le da seguridad$v$, updated_at = now()
WHERE id = 'objection.bala_repetida' AND resumen = $v$Repetir una bala tal cual: comunica que ya no tienes más, y baja el impulso en vez de subirlo. LA PRUEBA: como re-impulso, ¿el vendedor repite algo que ya había dicho —igual o con otras palabras— sin conectarlo con la objeción? Una bala ya dicha que ahora contesta la objeción («por eso le sale más barato: ya no pierde cambios») no es esto.$v$;

UPDATE public.node_cards SET body = $v$Más adelante en el mapa vas a ver qué pasa cuando el cliente pone una razón para no comprar.

Cuando eso ocurre, su impulso BAJA. Y responderle bien no lo sube: solo evita que siga cayendo.

Lo que lo vuelve a subir es una bala. Si ya las gastaste todas presumiendo al principio, llegas a ese momento con menos de dónde escoger. Por eso se dosifican.$v$
WHERE node_id = '4.5' AND card_order = 5 AND md5(concat_ws('|', card_order, coalesce(card_type,''), coalesce(title,''), coalesce(body,''), coalesce(flip_back_text,''))) = 'd917290dbeacd76f2f865d3a72967294';

UPDATE public.node_cards SET body = $v$Ya tienes todas las piezas. Así se arman:

CIERRAS CON ACCIÓN.
Si llega una objeción, el impulso BAJA.
La atraviesas con RRR o con FFF.
RE-IMPULSAS con una bala.
Y CIERRAS CON ACCIÓN otra vez.

Y si llega otra objeción, vuelves a girar. Eso es el Círculo de Cierre.$v$
WHERE node_id = '5.9' AND card_order = 1 AND md5(concat_ws('|', card_order, coalesce(card_type,''), coalesce(title,''), coalesce(body,''), coalesce(flip_back_text,''))) = '8cafa74b1137a682f175ef5f1e47d5c1';

UPDATE public.node_cards SET body = $v$Cada vuelta del círculo te pide una bala.

Si disparaste todo tu arsenal en la presentación porque querías impresionar, llegas a la tercera objeción con poco de dónde escoger. Puedes volver a decir una que ya usaste, y a veces ayuda: le confirma que lo que dijiste es verdad. Pero no siempre es la que mejor le pega a ese cliente.

El vendedor que dosificó llega a la tercera vuelta escogiendo. Por eso gana conversaciones que el otro pierde.$v$
WHERE node_id = '5.9' AND card_order = 3 AND md5(concat_ws('|', card_order, coalesce(card_type,''), coalesce(title,''), coalesce(body,''), coalesce(flip_back_text,''))) = '9bfa0733c58afe3bc730ea1fbde41b20';

UPDATE public.node_cards SET body = $v$Cuando llega la objeción:

1. ATRAVIESA — con RRR si es menor, con FFF si es de verdad.
2. RE-IMPULSA — una bala: la que escojas para volver a subirle el ánimo a ese cliente.
3. CIERRA CON ACCIÓN — el siguiente paso concreto.

En ese orden, y sin saltarte el dos. Ojo: en FFF, "lo que encontramos" no es la bala. La bala va aparte, después.$v$
WHERE node_id = '5.10' AND card_order = 1 AND md5(concat_ws('|', card_order, coalesce(card_type,''), coalesce(title,''), coalesce(body,''), coalesce(flip_back_text,''))) = '70433a02bae560897ef9e0ec982542f9';

UPDATE public.node_cards SET title = $v$La bala la escoges tú$v$, body = $v$Puede ser una que no habías dicho, o una que ya dijiste.

Volver a decir una ya dicha también se vale: no pega igual que una nueva, pero muchas veces ayuda, porque le confirma que lo que le dijiste es verdad. Y pega más si la conectas con su objeción. Si te dijo "está caro": "por eso le sale más barato: ya no pierde cambios por quedarse sin aceite".

Unas balas les pegan más a unos clientes que a otros. Leer cuál te conviene en ese momento es tu trabajo. Y por eso se dosifica: el que gastó todo presumiendo al principio llega aquí con menos de dónde escoger.$v$
WHERE node_id = '5.10' AND card_order = 3 AND md5(concat_ws('|', card_order, coalesce(card_type,''), coalesce(title,''), coalesce(body,''), coalesce(flip_back_text,''))) = 'e998a7c6569578da900ad46c06062853';

UPDATE public.node_cards SET body = $v$Resolviste "está caro" con tu mejor cuenta... y el cliente suelta: "sí, pero es que además ya tengo proveedor de años." Y detrás de esa, puede venir otra.

No es mala señal: es su proceso. Está sacando TODAS sus dudas antes del sí. La cadena es la antesala de la decisión.

Tu examen doble: cada objeción con SU bala (una sola, la que le convenga a esa objeción; la apilada abruma), y tu ánimo idéntico en la primera y en la última. El cliente está midiendo tu temple tanto como tus respuestas.$v$
WHERE node_id = '5.12' AND card_order = 1 AND md5(concat_ws('|', card_order, coalesce(card_type,''), coalesce(title,''), coalesce(body,''), coalesce(flip_back_text,''))) = '69a966b93900f7bae46528c3fc625edf';

UPDATE public.node_quiz_questions SET explanation_correct = $v$Correcto. Cuando el cliente ponga una razón para no comprar, lo que vuelve a subir su impulso es una bala. Si ya las gastó todas, llega con menos de dónde escoger.$v$
WHERE node_id = '4.5' AND question_order = 3 AND md5(concat_ws('|', coalesce(question_text,''), coalesce(option_a,''), coalesce(option_b,''), coalesce(option_c,''), coalesce(option_d,''), coalesce(correct_option,''), coalesce(explanation_correct,''), coalesce(explanation_wrong,''), coalesce(regla_id,''))) = 'e2eae6d489d86539388c737e46cc4dc7';

UPDATE public.node_quiz_questions SET option_b = $v$Porque cada vuelta del círculo te pide una bala, y si ya las gastaste todas te queda menos de dónde escoger.$v$, explanation_correct = $v$Correcto. El que dosificó llega a la tercera vuelta escogiendo la bala que mejor le pega a ese cliente. El que vació el cargador solo puede volver a decir lo que ya dijo: a veces ayuda, pero no siempre es lo que más le pega.$v$, explanation_wrong = $v$Es por la munición: cada objeción pide una bala para volver a subir el impulso. Si las guardaste, puedes escoger la que mejor le pega a ese cliente.$v$
WHERE node_id = '5.9' AND question_order = 3 AND md5(concat_ws('|', coalesce(question_text,''), coalesce(option_a,''), coalesce(option_b,''), coalesce(option_c,''), coalesce(option_d,''), coalesce(correct_option,''), coalesce(explanation_correct,''), coalesce(explanation_wrong,''), coalesce(regla_id,''))) = '8f029ac565ba323a8646092a1fb66d64';

